using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "AnchorJudgementCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/AnchorJudgementCustomDescription", order = 0)]
public class AnchorJudgementCustomDescription : CustomBattleActionDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		AnchorJudgementAction anchorJudgementAction = battleAction as AnchorJudgementAction;
		string firstArgument = anchorJudgementAction.PurifyAction.GetActionDescription(-1).RemoveLast();
		return base.localizationManager.GetLocalizedWhereX(firstArgument, amountModified == "-1", Smart.Format(GetRawLocalizedDescription(battleAction), anchorJudgementAction.CorruptionPercentToPurify));
	}
}
